class Solution {
    public int minPairSum(int[] nums) {
        java.util.Arrays.sort(nums);
        int left = 0;
        int right = nums.length - 1;
        int answer = 0;

        while (left < right) {
            answer = Math.max(answer, nums[left] + nums[right]);
            left++;
            right--;
        }
        return answer;
    }
}

class Solution {
    public int minPairSum(int[] nums) {
        java.util.Arrays.sort(nums);
        int low = nums[0] + nums[1];
        int high = nums[nums.length - 2] + nums[nums.length - 1];

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canPairWithin(nums, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean canPairWithin(int[] nums, int limit) {
        int left = 0;
        int right = nums.length - 1;
        while (left < right) {
            if ((long) nums[left] + nums[right] > limit) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

class Solution {
    public int minPairSum(int[] nums) {
        java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
        for (int value : nums) {
            counts.merge(value, 1, Integer::sum);
        }

        int answer = 0;
        while (!counts.isEmpty()) {
            int low = counts.firstKey();
            take(counts, low);
            int high = counts.lastKey();
            take(counts, high);
            answer = Math.max(answer, low + high);
        }
        return answer;
    }

    private void take(java.util.TreeMap<Integer, Integer> counts, int value) {
        int remaining = counts.get(value) - 1;
        if (remaining == 0) {
            counts.remove(value);
        } else {
            counts.put(value, remaining);
        }
    }
}
